public List<Payment> FindUnmatchedPayments(List<Payment> payments, List<Invoice> invoices)
{
    var unmatched = new List<Payment>();
    foreach (var p in payments)
    {
        var match = invoices.FirstOrDefault(i =>
            i.CustomerId == p.CustomerId && i.Amount == p.Amount);
        if (match == null) unmatched.Add(p);
    }
    return unmatched;
}

