public async Task<IActionResult> Transfer(TransferRequest req)
{
    var conn = new SqlConnection(_config["Db:ConnectionString"]);
    conn.Open();

    var cmd = new SqlCommand(
        $"SELECT Balance FROM Accounts WHERE AccountId = '{req.FromAccount}'", conn);
    var balance = (decimal)cmd.ExecuteScalar();

    if (balance < req.Amount)
        return BadRequest("Insufficient funds");

    await _repo.DebitAsync(req.FromAccount, req.Amount);
    await _repo.CreditAsync(req.ToAccount, req.Amount);

    _logger.LogInformation($"Transferred {req.Amount} from {req.FromAccount} to {req.ToAccount}");

    return Ok();
}

class Program
{
    static async Task Main()
    {
        Console.WriteLine("A");
        FireAndForget();
        Console.WriteLine("B");

        try { await ThrowsTwice(); }
        catch (Exception ex) { Console.WriteLine($"Caught: {ex.Message}"); }

        await Task.Delay(500);
        Console.WriteLine("E");
    }

    static async void FireAndForget()
    {
        Console.WriteLine("C");
        await Task.Delay(100);
        Console.WriteLine("D");
        throw new InvalidOperationException("boom");
    }

    static async Task ThrowsTwice()
    {
        var t1 = Task.Run(() => throw new InvalidOperationException("first"));
        var t2 = Task.Run(() => throw new ArgumentException("second"));
        await Task.WhenAll(t1, t2);
    }
}

