public async Task<List<LoanDto>> GetActiveLoansAsync()
{
    var loans = await _db.Loans
        .Where(l => l.Status == "Active")
        .ToListAsync();

    var result = new List<LoanDto>();
    foreach (var loan in loans)
    {
        result.Add(new LoanDto
        {
            Id = loan.Id,
            BorrowerName = loan.Borrower.FullName,          // lazy loaded
            TotalPaid = loan.Payments.Sum(p => p.Amount),   // lazy loaded
            LatestNote = loan.Notes.OrderByDescending(n => n.CreatedAt).First().Text
        });
    }
    return result;
}

